/**
 ******************************************************************************
 * @file    rate_adapter.h
 * TEAM CODE (owner: Tom - sound output and effects) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: written by Brendon (integrator) on 29-30 Oct 2026 for Tom's sound output subsystem (best-ui), with an AI coding assistant.
 * @brief   2:3 rate adapter: 32 kHz mono samples in, 48 kHz mono samples out.
 *
 * What it does: recordings are made at 32 kHz, but the speaker DAC (I2S3)
 * and every effect run at 48 kHz. For every 2 input samples this makes 3
 * output samples, by drawing a straight line between neighbouring input
 * samples (linear interpolation). It is the upsampler TomTask has always
 * used (upsample_block() in tom_dac_output.c), moved here with the same
 * arithmetic, so that two tasks can share it and the host tests can check
 * it against the old copy sample for sample.
 *
 * Who runs it: TomTask (playing a 32 kHz recording) and FxRenderTask
 * (inside FxRender, making an effect file from a 32 kHz recording). Each
 * keeps its own RateAdapter2to3, so neither disturbs the other. Pure: no
 * RTOS, no HAL, compiles on any host (tests:
 * Tests/OutputChain/test_rate_adapter.c).
 *
 * Main steps:
 *   1. RateAdapter2to3_Reset()    at the start of a sound: the sample before
 *                                 the first one counts as silence (0)
 *   2. RateAdapter2to3_Process()  for each block of n input samples: writes
 *                                 (3 x n) / 2 output samples and remembers
 *                                 the block's last sample, so the next block
 *                                 carries on without a step
 *   RateAdapter2to3_InputThatFits() is for TomTask only, just before step 2
 *   on each block: how many of the block's samples still fit in the rest of
 *   a 4 ms half.
 ******************************************************************************
 */
#ifndef RATE_ADAPTER_H
#define RATE_ADAPTER_H

#include <stdint.h>

/** The only state: the last input sample of the previous block. */
typedef struct
{
    int16_t last_in;
} RateAdapter2to3;

/**
 * @brief Start a new sound: the sample before the first one is 0.
 * @param adapter State to reset. NULL is safely ignored.
 */
void RateAdapter2to3_Reset(RateAdapter2to3 *adapter);

/**
 * @brief Turn n_in samples at 32 kHz into (3 x n_in) / 2 samples at 48 kHz.
 *
 * An odd n_in gives the lower whole number (41 in -> 61 out), exactly as
 * TomTask's upsampler always did.
 *
 * @param adapter State carried from block to block.
 * @param in_32k  n_in input samples.
 * @param n_in    Number of input samples (a block is at most 64 in practice).
 * @param out_48k Room for (3 x n_in) / 2 output samples.
 * @return The number of output samples written. 0 for n_in == 0 or a NULL
 *         pointer, and then the state is unchanged.
 */
uint32_t RateAdapter2to3_Process(RateAdapter2to3 *adapter,
                                 const int16_t *in_32k,
                                 uint32_t n_in,
                                 int16_t *out_48k);

/**
 * @brief How many of n_in input samples to upsample when only room_out
 *        output samples are left (TomTask: the rest of a half).
 *
 * n_in itself when its (3 x n_in) / 2 outputs fit, otherwise the most that
 * fit. Never 0 while n_in and room_out are at least 1: the old rule
 * (room_out x 2) / 3 gave 0 for a room of 1, and TomTask then threw away
 * every queued block until the queue ran dry (an underrun at every loop of
 * an odd-length 32 kHz file).
 *
 * @param n_in     Input samples on offer (one block: 1..64).
 * @param room_out Output samples still free (1..192 in TomTask).
 * @return The number of input samples to give RateAdapter2to3_Process().
 */
uint32_t RateAdapter2to3_InputThatFits(uint32_t n_in, uint32_t room_out);

#endif
